window.RP_SESSION={"id":"S-626d8bad40ae","messages":[{"id":"RP-0106236","time":"2026-04-09T16:43:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"흠흠···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106237","time":"2026-04-09T16:43:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"똑똑, @GM 의 방을 울리는 가벼운 노크 소리.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106238","time":"2026-04-09T16:43:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"예, 들어오세요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106239","time":"2026-04-09T16:44:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"문을 열고서는 마리우스가 빼곰, 들어섭니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106240","time":"2026-04-09T16:44:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 션이 공대장 된 기념으로···. 파티를 좀 하려고 하는데요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106241","time":"2026-04-09T16:44:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"흠...\"","characters":["P-e6655a038328"]},{"id":"RP-0106242","time":"2026-04-09T16:44:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐, 그러죠.\"","characters":["P-e6655a038328"]},{"id":"RP-0106243","time":"2026-04-09T16:45:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"준비는 마리우스에게 맡기면 되는거죠?\"","characters":["P-e6655a038328"]},{"id":"RP-0106244","time":"2026-04-09T16:45:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아! 네, 그럼요, 그럼요. 제가 책임지고 잘 준비할게요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106245","time":"2026-04-09T16:46:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"얼마나 크게 열 생각이에요?\"","characters":["P-e6655a038328"]},{"id":"RP-0106246","time":"2026-04-09T16:46:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 길드 앞에서요, 캠핑장이나 길드 회관 생각 중인데···. 어느 쪽이 괜찮을 것 같으세요? ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106247","time":"2026-04-09T16:46:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실 뭐든간에 상관은 없는데 죄다 돈이 문제니까요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106248","time":"2026-04-09T16:46:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아 저···. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106249","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"혹시 션이 공격대장이 된 겸에서 자기가 낸다고 하던가요?\"","characters":["P-e6655a038328"]},{"id":"RP-0106250","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저금, 해둔 돈이 있긴 한데요···. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106251","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 제가 해드리고 싶어서요, 그냥, 개인적으로. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106252","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 스승님이시잖아요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106253","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...?\"","characters":["P-e6655a038328"]},{"id":"RP-0106254","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"눈치봅니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106255","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"마리우스, 생각보다 씀씀이가 헤프네요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106256","time":"2026-04-09T16:47:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그렇게 하나하나 챙겨주면 주머니에 아무것도 안 남아요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106257","time":"2026-04-09T16:48:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실상 션이랑 만난지도 몇주 되지도 않은 것 아니에요?\"","characters":["P-e6655a038328"]},{"id":"RP-0106258","time":"2026-04-09T16:48:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아하하, 하, 션은 좀, 다른 느낌이랄까요. 언제든 해드리고 싶은 맘이 있어서. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106259","time":"2026-04-09T16:48:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"... 혹시 개인적인 감정이 있어요? 션에게?\"","characters":["P-e6655a038328"]},{"id":"RP-0106260","time":"2026-04-09T16:49:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"뜨끔.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106261","time":"2026-04-09T16:49:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아니??! 아니요? 아니요! ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106262","time":"2026-04-09T16:49:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 스승은 다른 느낌이잖아요, 은혜라고 해야하나. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106263","time":"2026-04-09T16:49:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"흐음....\"","characters":["P-e6655a038328"]},{"id":"RP-0106264","time":"2026-04-09T16:49:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"솔직히 설득력 없는거 알죠?\"","characters":["P-e6655a038328"]},{"id":"RP-0106265","time":"2026-04-09T16:51:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"무슨 만난지 몇 주 되지도 않는 스승을 제자가 이렇게 챙긴다는건지...\"","characters":["P-e6655a038328"]},{"id":"RP-0106266","time":"2026-04-09T16:52:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"솔직하게 말해요 그냥. 저희 길드가 무슨 남녀 사이가 유별난 이상한 곳도 아니고.\"","characters":["P-e6655a038328"]},{"id":"RP-0106267","time":"2026-04-09T16:52:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 션 씨는, 잘 이끌어주셨어요. 감정에 흔들리는 검도. 쉽게 포기하는 제 맘도 그렇고요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106268","time":"2026-04-09T16:52:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 개인적인 감정이 없다고는 말을 못하지만···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106269","time":"2026-04-09T16:53:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"바쁘니까. 그냥 제가 이해하기로는 션은 모르겠지만 마리우스는 션에게 감정이 있단 최소 있는 것으로 보이고 션을 위해서 축하 파티를 연다는거죠?\"","characters":["P-e6655a038328"]},{"id":"RP-0106270","time":"2026-04-09T16:53:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"기각.\"","characters":["P-e6655a038328"]},{"id":"RP-0106271","time":"2026-04-09T16:53:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"션이 내거나 다 같이 내거나 하세요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106272","time":"2026-04-09T16:54:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"좋아하는 사람한테 그렇게 다 해주다가 좋은 꼴 못봐요. 하물며 션? 딸이 있는지도 모르던 양반한테 그렇게 홀딱 넘어가지 말고 좀 더 냉철해지세요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106273","time":"2026-04-09T16:56:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"자 바빠요. 나가요. 훠이훠이.\"","characters":["P-e6655a038328"]},{"id":"RP-0106274","time":"2026-04-09T16:56:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"윽.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106275","time":"2026-04-09T16:56:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 교제, 교제해요, 교제···. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106276","time":"2026-04-09T16:57:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 연인으로서는 해줄 수 있죠? 아무래도. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106277","time":"2026-04-09T16:58:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그닥 밝힐 생각은 없었으나, 조용히 서서···.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106278","time":"2026-04-09T16:58:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"안되는 이유가 개인적인 생각과 부길드장의 입장이 하나씩 있는데 어떤 것을 먼저 들을래요?\"","characters":["P-e6655a038328"]},{"id":"RP-0106279","time":"2026-04-09T16:59:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"둘 다 듣고 싶지 않아아. 이윽고.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106280","time":"2026-04-09T16:59:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 부길드장 입장에서 들어볼게요, 그리고···. 그, 그 전에. 저는 따로 부수입원이 있기도 해요. 우선, 알고만 있어주시라고···. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106281","time":"2026-04-09T17:01:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"먼저, 파티 자체는 찬성이에요. 하지만 션이 그래도 모두의 상관인 공격대장이 되는 것이니까. 그런 자리를 축하한다고 다른 사람이 여는 것 까지는 어느정도 감안할 수 있겠다만 한턱 내는 것은 션이어야 해요. 사람은 생각보다 단순해요. 한턱 쏘면 아 밥 얻어먹었으니까 도와줘야지라는 생각이 최소한 생기니까요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106282","time":"2026-04-09T17:04:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 으음, 그렇죠. 아무래도 금액적 관련으로는 션이 책임 지는 게 맞을 것 같아요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0106283","time":"2026-04-09T17:05:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그리고 개인적인 이유는. 그냥 심술이에요. 루체 때문에 골머리 썩히고 있었는데 그 원망의 대상이 생겼으니까요. 티아 언니에 대한 기억은 솔직히 시간이 지나서 막 엄청 많이 나지는 않지만... 그렇다고 마리우스랑 이렇게 꽁냥대는 모습을 본다고 생각하면 조금은 짜증이 나네요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106284","time":"2026-04-09T17:05:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그러니까 션의 주머니라도 털어야겠어요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106285","time":"2026-04-09T17:18:00+09:00","room":"RP","name":"스텔라","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이제 진짜 나가봐요. 저 바빠요.\"","characters":["P-e6655a038328"]},{"id":"RP-0106286","time":"2026-04-09T17:18:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 가만히 스텔라의 대답을 듣다가, 빵 터져서 웃음 흘립니다.\n\n“ 고마워요. ”\n\n짧은 말 남기고···. 문 닫고 사라집니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0106287","time":"2026-04-09T19:54:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-0106288","time":"2026-04-09T19:54:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
